import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "../styles/signup.css";

const SubscriptionPlans = ({ onContinue }) => {
  const plans = [
    { id: 1, duration: "1 Week", price: "$17.99/wk", popular: true },
    { id: 2, duration: "1 Month", price: "$12.50/wk", popular: false },
    { id: 3, duration: "6 Months", price: "$10.00/wk", popular: false },
  ];

  const [selectedPlan, setSelectedPlan] = useState(plans[0]);

  return (
    <div className="subscription-container">
      <h2 className="subscription-title">Your likes will be seen sooner with Priority Likes.</h2>
      <p className="subscription-subtitle">Select a plan</p>
      <div className="plans">
        {plans.map((plan) => (
          <div
            key={plan.id}
            className={`plan ${selectedPlan.id === plan.id ? "selected" : ""}`}
            onClick={() => setSelectedPlan(plan)}
          >
            {plan.popular && <span className="popular">Popular</span>}
            <h3>{plan.duration}</h3>
            <p>{plan.price}</p>
          </div>
        ))}
      </div>
      <div className="features">
        <p>✔ Unlimited Likes</p>
        <p>✔ See Who Likes You</p>
        <p>✔ Priority Likes</p>
      </div>
      <button className="continue-btn" onClick={() => onContinue(selectedPlan)}>
        Continue - {selectedPlan.price} total
      </button>
    </div>
  );
};

const Signup = () => {
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    password: "",
  });
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [showSubscription, setShowSubscription] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e) => {
    const { name, value } = e.target;

    if ((name === "firstName" || name === "lastName") && !/^[a-zA-Z]*$/.test(value)) {
      return;
    }

    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const { firstName, lastName, email, password } = formData;

    if (!firstName || !lastName || !email || !password || !confirmPassword) {
      setError("All fields are required.");
      return;
    }

    if (!/\S+@\S+\.\S+/.test(email)) {
      setError("Please enter a valid email address.");
      return;
    }

    if (password.length < 6) {
      setError("Password must be at least 6 characters long.");
      return;
    }

    if (password !== confirmPassword) {
      setError("Passwords do not match.");
      return;
    }

    setError("");
    setShowSubscription(true);
  };

  const handleSubscriptionContinue = (selectedPlan) => {
    console.log("Selected Plan:", selectedPlan);
    navigate("/");
  };

  return (
    <div className="signup-page">
      {showSubscription ? (
        <SubscriptionPlans onContinue={handleSubscriptionContinue} />
      ) : (
        <div className="signup-container">
          <h1 className="signup-title">Join To MAX<span className="highlight">PAIN</span></h1>
          <form className="signup-form" onSubmit={handleSubmit}>
            <div className="form-group">
              <label htmlFor="firstName">First Name</label>
              <input
                type="text"
                id="firstName"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                placeholder="Enter your first name"
              />
            </div>
            <div className="form-group">
              <label htmlFor="lastName">Last Name</label>
              <input
                type="text"
                id="lastName"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                placeholder="Enter your last name"
              />
            </div>
            <div className="form-group">
              <label htmlFor="email">Email Address</label>
              <input
                type="email"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="Enter your email address"
              />
            </div>
            <div className="form-group">
              <label htmlFor="password">Password</label>
              <div className="password-input-container" style={{ position: 'relative' }}>
                <input
                  type="password"
                  id="password"
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  placeholder="Enter your password"
                  style={{ paddingRight: '30px', width: '95%' }}
                />
                <span
                  className="password-toggle-icon"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{ position: 'absolute', right: '10px', top: '50%', transform: 'translateY(-50%)', cursor: 'pointer' }}
                >
                  👁️
                </span>
              </div>
            </div>
            <div className="form-group">
              <label htmlFor="confirmPassword">Confirm Password</label>
              <div className="password-input-container" style={{ position: 'relative' }}>
                <input
                  type="password"
                  id="confirmPassword"
                  name="confirmPassword"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder="Confirm your password"
                  style={{ paddingRight: '30px', width: '95%' }}
                />
                <span
                  className="password-toggle-icon"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{ position: 'absolute', right: '10px', top: '50%', transform: 'translateY(-50%)', cursor: 'pointer' }}
                >
                  👁️
                </span>
              </div>
            </div>
            {error && <p className="error-message">{error}</p>}
            <button type="submit" className="signup-btn">Sign up</button>
          </form>
          <p className="login-link">
            Already have an account? <a href="/login">Log in</a>
          </p>
        </div>
      )}
    </div>
  );
};

export default Signup;
